-- Additive migration. Existing waitlist data is deliberately untouched.
CREATE TABLE shaz_user(id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE shaz_session(id text PRIMARY KEY, "userId" text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE, token text NOT NULL UNIQUE, "expiresAt" timestamptz NOT NULL, "ipAddress" text, "userAgent" text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX shaz_session_user_idx ON shaz_session("userId");
CREATE TABLE shaz_account(id text PRIMARY KEY, "userId" text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE, "accountId" text NOT NULL, "providerId" text NOT NULL, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX shaz_account_user_idx ON shaz_account("userId");
CREATE TABLE shaz_verification(id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX shaz_verification_identifier_idx ON shaz_verification(identifier);
CREATE TABLE shaz_rate(key text PRIMARY KEY, count integer NOT NULL, expires timestamptz NOT NULL);
CREATE TABLE shaz_orders(id text PRIMARY KEY, checkout_id text UNIQUE NOT NULL, payment_id text UNIQUE, email text NOT NULL, user_id text REFERENCES shaz_user(id) ON DELETE SET NULL, amount integer NOT NULL CHECK(amount=39900), currency text NOT NULL CHECK(currency='dkk'), livemode boolean NOT NULL, status text NOT NULL CHECK(status IN ('pending','paid','refunded','disputed','failed')), product text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz, terms_version text NOT NULL, receipt jsonb NOT NULL DEFAULT '{}', refunded_amount integer NOT NULL DEFAULT 0);
CREATE INDEX shaz_orders_email_idx ON shaz_orders(email);
CREATE TABLE shaz_events(id text PRIMARY KEY, type text NOT NULL, processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shaz_checkout(id text PRIMARY KEY, token_hash text UNIQUE NOT NULL, checkout_id text UNIQUE, email text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shaz_profile(user_id text PRIMARY KEY REFERENCES shaz_user(id) ON DELETE CASCADE, step integer NOT NULL DEFAULT 0, data jsonb NOT NULL DEFAULT '{}', start_date date, timezone text NOT NULL DEFAULT 'Europe/Copenhagen', version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shaz_days(id text PRIMARY KEY, user_id text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE, day integer NOT NULL CHECK(day BETWEEN 1 AND 100), scheduled_date date NOT NULL, plan jsonb NOT NULL, status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','completed','skipped','rest')), log jsonb NOT NULL DEFAULT '{}', completed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,day));
CREATE INDEX shaz_days_user_idx ON shaz_days(user_id,scheduled_date);
CREATE TABLE shaz_checkins(id text PRIMARY KEY, user_id text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE, week integer NOT NULL CHECK(week BETWEEN 1 AND 15), data jsonb NOT NULL, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,week));
CREATE TABLE shaz_weights(id text PRIMARY KEY,user_id text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE, date date NOT NULL, kg numeric NOT NULL CHECK(kg BETWEEN 30 AND 350), UNIQUE(user_id,date));
CREATE TABLE shaz_favorites(user_id text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE, recipe_id text NOT NULL, PRIMARY KEY(user_id,recipe_id));
CREATE TABLE shaz_meals(id text PRIMARY KEY,user_id text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE, date date NOT NULL, slot text NOT NULL, recipe_id text NOT NULL, servings numeric NOT NULL CHECK(servings BETWEEN 0.5 AND 12), recipe jsonb NOT NULL, UNIQUE(user_id,date,slot));
CREATE TABLE shaz_shopping(user_id text NOT NULL REFERENCES shaz_user(id) ON DELETE CASCADE, week text NOT NULL, ingredient_id text NOT NULL, checked boolean NOT NULL, PRIMARY KEY(user_id,week,ingredient_id));
CREATE TABLE shaz_content(kind text NOT NULL, id text NOT NULL, version integer NOT NULL, status text NOT NULL CHECK(status IN ('draft','review','published')), data jsonb NOT NULL, reviewer_id text REFERENCES shaz_user(id), reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(kind,id,version));
CREATE TABLE shaz_roles(user_id text PRIMARY KEY REFERENCES shaz_user(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','editor')));
CREATE TABLE shaz_invites(token_hash text PRIMARY KEY, email text NOT NULL, role text NOT NULL CHECK(role IN ('owner','editor')), expires timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE shaz_audit(id text PRIMARY KEY, actor_id text, action text NOT NULL, target text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shaz_mail(id text PRIMARY KEY, email text NOT NULL, kind text NOT NULL, payload text, provider_id text UNIQUE, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, error_code text, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE TABLE shaz_refunds(id text PRIMARY KEY, user_id text REFERENCES shaz_user(id) ON DELETE SET NULL, order_id text NOT NULL REFERENCES shaz_orders(id), reason text NOT NULL, status text NOT NULL DEFAULT 'requested', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id));
CREATE TABLE shaz_videos(id text PRIMARY KEY, name text NOT NULL, mime text NOT NULL, bytes bigint NOT NULL, uploaded_by text NOT NULL REFERENCES shaz_user(id), created_at timestamptz NOT NULL DEFAULT now());
